import math
def is_prime(n):
    if n <= 1:
        return False
    if n <= 3:
        return True
    if n % 2 == 0 or n % 3 == 0:
        return False
    i = 5
    while i * i <= n:
        if n % i == 0 or n % (i + 2) == 0:
            return False
        i += 6
    return True

print(f"Is {K} prime? {is_prime(K)}")

# If not prime, try to find factors
factors = []
for i in range(1, int(math.sqrt(K)) + 1):
    if K % i == 0:
        factors.append(i)
        factors.append(K // i)

print(f"Factors found: {sorted(factors)}")

